select s.region, case when s.region in ('West', 'North') then 'core' else 'other' end region_group, count(ss.units) units_count, max(ss.revenue) max_revenue from store_sales ss join products p on ss.product_id = p.id join stores s on ss.store_id = s.id where ss.store_id in (1, 4, 6) group by s.region, case when s.region in ('West', 'North') then 'core' else 'other' end order by units_count
